function topic(path) {
  if (/turnaround|performance-pressure/.test(path)) return "turnaround";
  if (/multi-location/.test(path)) return "multi";
  if (/tax/.test(path)) return "tax";
  if (/compliance/.test(path)) return "compliance";
  if (/tip/.test(path)) return "tips";
  if (/payroll/.test(path)) return "payroll";
  if (/labor|scheduling|attendance/.test(path)) return "labor";
  if (/inventory/.test(path)) return "inventory";
  if (/food-cost|vendor-price/.test(path)) return "food";
  if (/payable|vendor-bill/.test(path)) return "payables";
  if (/cash/.test(path)) return "cash";
  if (/cfo|reporting/.test(path)) return "cfo";
  if (/profit/.test(path)) return "profit";
  if (/consulting/.test(path)) return "consulting";
  if (/bookkeeping|books-behind/.test(path)) return "bookkeeping";
  if (/accounting/.test(path)) return "accounting";
  if (/back-office/.test(path)) return "backoffice";
  return "finance";
}

