for (const [path, [heading, description]] of Object.entries(directories)) main[path] = copy(heading, description);

const files = ["site", "service-pages", "solution-pages", "answer-pages", "search-pages", "nyc-intent-pages"];
const documents = Object.fromEntries(files.map(file => [file, JSON.parse(fs.readFileSync(`content/${file}.json`, "utf8"))]));
for (const file of ["service-pages", "search-pages", "nyc-intent-pages"]) {
  for (const page of documents[file].pages) {
    if (page.kind === "article") continue;
    const replacement = structuredClone(services[topic(page.path)]);
    if (page.path.startsWith("/new-york")) {
      replacement.heading = page.path === "/new-york" ? "A finance team for your New York restaurant." : replacement.heading;
      replacement.description = replacement.description.replace(/^Restaurant /, "New York restaurant ") + " Service responsibilities are confirmed for your locations.";
    }
    Object.assign(page, replacement);
    page.answer = replacement.description;
  }
}
for (const page of documents.site.pages) {
  if (main[page.path]) Object.assign(page, structuredClone(main[page.path]));
  else if (page.kind === "capability") Object.assign(page, structuredClone(services[topic(page.path)]));
}

